	"cbdc": "CBDC", "bitcoin": "BITCOIN",
	"cbdc_point_1": "\u0391\u03C0\u03B1\u03B9\u03C4\u03B5\u03AF \u03AC\u03B4\u03B5\u03B9\u03B1", "cbdc_point_2": "\u03A4\u03B1 \u03C7\u03C1\u03AE\u03BC\u03B1\u03C4\u03AC \u03C3\u03B1\u03C2 \u03BC\u03C0\u03BF\u03C1\u03BF\u03CD\u03BD \u03BD\u03B1 \u03BB\u03AE\u03BE\u03BF\u03C5\u03BD", "cbdc_point_3": "\u039A\u03B1\u03BD\u03AD\u03BD\u03B1 \u03CC\u03C1\u03B9\u03BF \u03C3\u03C5\u03BD\u03BF\u03BB\u03B9\u03BA\u03AE\u03C2 \u03C0\u03C1\u03BF\u03C3\u03C6\u03BF\u03C1\u03AC\u03C2", "cbdc_point_4": "\u03A3\u03C5\u03BD\u03B4\u03B5\u03B4\u03B5\u03BC\u03AD\u03BD\u03BF \u03BC\u03B5 \u03BA\u03C1\u03B1\u03C4\u03B9\u03BA\u03AE \u03C4\u03B1\u03C5\u03C4\u03CC\u03C4\u03B7\u03C4\u03B1", "cbdc_point_5": "\u039A\u03B5\u03BD\u03C4\u03C1\u03B9\u03BA\u03BF\u03C0\u03BF\u03B9\u03B7\u03BC\u03AD\u03BD\u03BF", "cbdc_point_6": "\u039F\u03B9 \u03C7\u03C1\u03AE\u03C3\u03C4\u03B5\u03C2 \u03B4\u03B5\u03BD \u03BC\u03C0\u03BF\u03C1\u03BF\u03CD\u03BD \u03BD\u03B1 \u03C4\u03C1\u03AD\u03BE\u03BF\u03C5\u03BD \u03BA\u03CC\u03BC\u03B2\u03BF\u03C5\u03C2", "cbdc_point_7": "\u0395\u03CD\u03BA\u03BF\u03BB\u03B1 \u03C0\u03B1\u03B3\u03CE\u03C3\u03B9\u03BC\u03BF", "cbdc_point_8": "\u03A0\u03C1\u03AD\u03C0\u03B5\u03B9 \u03BD\u03B1 \u03B5\u03BC\u03C0\u03B9\u03C3\u03C4\u03B5\u03C5\u03C4\u03B5\u03AF\u03C4\u03B5 \u03B8\u03B5\u03BC\u03B1\u03C4\u03BF\u03C6\u03CD\u03BB\u03B1\u03BA\u03B5\u03C2", "cbdc_point_9": "\u039C\u03B5\u03C4\u03B1\u03B2\u03BB\u03B7\u03C4\u03AE \u03BD\u03BF\u03BC\u03B9\u03C3\u03BC\u03B1\u03C4\u03B9\u03BA\u03AE \u03C0\u03BF\u03BB\u03B9\u03C4\u03B9\u03BA\u03AE", "cbdc_point_10": "\u0391\u03BD\u03B1\u03C3\u03C6\u03B1\u03BB\u03AD\u03C2",
	"bitcoin_point_1": "\u03A7\u03C1\u03AE\u03C3\u03B7 \u03C7\u03C9\u03C1\u03AF\u03C2 \u03AC\u03B4\u03B5\u03B9\u03B1", "bitcoin_point_2": "\u03A4\u03B1 \u03C7\u03C1\u03AE\u03BC\u03B1\u03C4\u03AC \u03C3\u03B1\u03C2 \u03B4\u03B5\u03BD \u03BB\u03AE\u03B3\u03BF\u03C5\u03BD \u03C0\u03BF\u03C4\u03AD", "bitcoin_point_3": "\u03A3\u03C4\u03B1\u03B8\u03B5\u03C1\u03AE \u03C0\u03C1\u03BF\u03C3\u03C6\u03BF\u03C1\u03AC 21M BTC", "bitcoin_point_4": "\u03A8\u03B5\u03C5\u03B4\u03CE\u03BD\u03C5\u03BC\u03BF", "bitcoin_point_5": "\u0391\u03C0\u03BF\u03BA\u03B5\u03BD\u03C4\u03C1\u03C9\u03BC\u03AD\u03BD\u03BF", "bitcoin_point_6": "\u039F\u03B9 \u03C7\u03C1\u03AE\u03C3\u03C4\u03B5\u03C2 \u03BC\u03C0\u03BF\u03C1\u03BF\u03CD\u03BD \u03BD\u03B1 \u03C4\u03C1\u03AD\u03BE\u03BF\u03C5\u03BD \u03BA\u03CC\u03BC\u03B2\u03BF\u03C5\u03C2", "bitcoin_point_7": "\u0394\u03B5\u03BD \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03C0\u03B1\u03B3\u03CE\u03C3\u03B5\u03B9", "bitcoin_point_8": "\u0394\u03C5\u03BD\u03B1\u03C4\u03CC\u03C4\u03B7\u03C4\u03B1 \u03B1\u03C5\u03C4\u03BF-\u03C6\u03CD\u03BB\u03B1\u03BE\u03B7\u03C2", "bitcoin_point_9": "\u03A0\u03C1\u03BF\u03B2\u03BB\u03AD\u03C8\u03B9\u03BC\u03B7 \u03BD\u03BF\u03BC\u03B9\u03C3\u03BC\u03B1\u03C4\u03B9\u03BA\u03AE \u03C0\u03BF\u03BB\u03B9\u03C4\u03B9\u03BA\u03AE", "bitcoin_point_10": "\u0391\u03C3\u03C6\u03B1\u03BB\u03AD\u03C2",
	"point_1_summary_1": "\u03A4\u03BF Bitcoin \u03C3\u03C7\u03B5\u03B4\u03B9\u03AC\u03C3\u03C4\u03B7\u03BA\u03B5 \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03C3\u03B1\u03C2 \u03B4\u03AF\u03BD\u03B5\u03B9 \u03C0\u03BB\u03AE\u03C1\u03B7 \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF \u03C4\u03C9\u03BD \u03C7\u03C1\u03B7\u03BC\u03AC\u03C4\u03C9\u03BD \u03C3\u03B1\u03C2.", "point_1_summary_2": "\u039A\u03B1\u03BD\u03B5\u03AF\u03C2 \u03B4\u03B5\u03BD \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03C3\u03B1\u03C2 \u03B5\u03BC\u03C0\u03BF\u03B4\u03AF\u03C3\u03B5\u03B9 \u03B1\u03C0\u03CC \u03C3\u03C5\u03BD\u03B1\u03BB\u03BB\u03B1\u03B3\u03AD\u03C2 Bitcoin.", "point_1_summary_3": "\u03A4\u03B1 CBDC \u03C3\u03C7\u03B5\u03B4\u03B9\u03AC\u03C3\u03C4\u03B7\u03BA\u03B1\u03BD \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03B4\u03AF\u03BD\u03BF\u03C5\u03BD \u03C3\u03C4\u03B9\u03C2 \u03BA\u03C5\u03B2\u03B5\u03C1\u03BD\u03AE\u03C3\u03B5\u03B9\u03C2 \u03C0\u03BB\u03AE\u03C1\u03B7 \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF \u03C4\u03C9\u03BD \u03C7\u03C1\u03B7\u03BC\u03AC\u03C4\u03C9\u03BD \u03C3\u03B1\u03C2.", "point_1_summary_4": "\u03A4\u03B1 CBDC \u03C0\u03B5\u03C1\u03B9\u03BF\u03C1\u03AF\u03B6\u03BF\u03C5\u03BD \u03C4\u03B7\u03BD \u03B9\u03B4\u03B9\u03C9\u03C4\u03B9\u03BA\u03CC\u03C4\u03B7\u03C4\u03B1 \u03BA\u03B1\u03B9 \u03C4\u03B7\u03BD \u03B5\u03BB\u03B5\u03C5\u03B8\u03B5\u03C1\u03AF\u03B1 \u03C3\u03B1\u03C2.",
	"point_2_summary_1": "\u03A4\u03BF Bitcoin \u03B4\u03B5\u03BD \u03BB\u03AE\u03B3\u03B5\u03B9 \u03C0\u03BF\u03C4\u03AD.", "point_2_summary_2": "\u03A4\u03B1 CBDC \u03BC\u03C0\u03BF\u03C1\u03BF\u03CD\u03BD \u03BD\u03B1 \u03C0\u03C1\u03BF\u03B3\u03C1\u03B1\u03BC\u03BC\u03B1\u03C4\u03B9\u03C3\u03C4\u03BF\u03CD\u03BD \u03BD\u03B1 \u03BB\u03AE\u03BE\u03BF\u03C5\u03BD.", "point_2_summary_3": "\u038C\u03C4\u03B1\u03BD \u03C4\u03B1 CBDC \u03BB\u03AE\u03B3\u03BF\u03C5\u03BD, \u03C3\u03B1\u03C2 \u03B5\u03BC\u03C0\u03BF\u03B4\u03AF\u03B6\u03BF\u03C5\u03BD \u03BD\u03B1 \u03B1\u03C0\u03BF\u03C4\u03B1\u03BC\u03B9\u03B5\u03CD\u03C3\u03B5\u03C4\u03B5 \u03B3\u03B9\u03B1 \u03C4\u03BF \u03BC\u03AD\u03BB\u03BB\u03BF\u03BD.",
