	"point_4_summary_1": "\u039F\u03B9 \u03B4\u03B9\u03B5\u03C5\u03B8\u03CD\u03BD\u03C3\u03B5\u03B9\u03C2 Bitcoin \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C8\u03B5\u03C5\u03B4\u03CE\u03BD\u03C5\u03BC\u03B5\u03C2. \u03A4\u03B1 CBDC \u03C3\u03C5\u03BD\u03B4\u03AD\u03BF\u03BD\u03C4\u03B1\u03B9 \u03B1\u03C0\u03B5\u03C5\u03B8\u03B5\u03AF\u03B1\u03C2 \u03BC\u03B5 \u03C4\u03B7\u03BD \u03C4\u03B1\u03C5\u03C4\u03CC\u03C4\u03B7\u03C4\u03AC \u03C3\u03B1\u03C2.",
	"point_5_summary_1": "\u03A4\u03BF \u03B4\u03AF\u03BA\u03C4\u03C5\u03BF Bitcoin \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B1\u03C0\u03BF\u03BA\u03B5\u03BD\u03C4\u03C1\u03C9\u03BC\u03AD\u03BD\u03BF.", "point_5_summary_2": "\u0394\u03B5\u03BA\u03AC\u03B4\u03B5\u03C2 \u03C7\u03B9\u03BB\u03B9\u03AC\u03B4\u03B5\u03C2 \u03B1\u03BD\u03B5\u03BE\u03AC\u03C1\u03C4\u03B7\u03C4\u03BF\u03B9 \u03BA\u03CC\u03BC\u03B2\u03BF\u03B9 \u03B5\u03C0\u03B9\u03B2\u03B5\u03B2\u03B1\u03B9\u03CE\u03BD\u03BF\u03C5\u03BD \u03C4\u03BF\u03C5\u03C2 \u03BA\u03B1\u03BD\u03CC\u03BD\u03B5\u03C2.", "point_5_summary_3": "\u03A4\u03B1 CBDC \u03B5\u03AF\u03BD\u03B1\u03B9 \u03BA\u03B5\u03BD\u03C4\u03C1\u03B9\u03BA\u03BF\u03C0\u03BF\u03B9\u03B7\u03BC\u03AD\u03BD\u03B1 \u03C3\u03C4\u03B1 \u03C7\u03AD\u03C1\u03B9\u03B1 \u03BA\u03C5\u03B2\u03B5\u03C1\u03BD\u03AE\u03C3\u03B5\u03C9\u03BD \u03BA\u03B1\u03B9 \u03BA\u03B5\u03BD\u03C4\u03C1\u03B9\u03BA\u03CE\u03BD \u03C4\u03C1\u03B1\u03C0\u03B5\u03B6\u03CE\u03BD.",
	"point_6_summary_1": "\u03A4\u03BF Bitcoin \u03B5\u03C0\u03B9\u03C4\u03C1\u03AD\u03C0\u03B5\u03B9 \u03C3\u03B5 \u03BF\u03C0\u03BF\u03B9\u03BF\u03BD\u03B4\u03AE\u03C0\u03BF\u03C4\u03B5 \u03BD\u03B1 \u03C4\u03C1\u03AD\u03BE\u03B5\u03B9 \u03BA\u03CC\u03BC\u03B2\u03BF. \u03A4\u03B1 CBDC \u03B4\u03B5\u03BD \u03B5\u03C0\u03B9\u03C4\u03C1\u03AD\u03C0\u03BF\u03C5\u03BD \u03BA\u03CC\u03BC\u03B2\u03BF\u03C5\u03C2.",
	"point_7_summary_1": "\u03A4\u03BF Bitcoin \u03C3\u03C7\u03B5\u03B4\u03B9\u03AC\u03C3\u03C4\u03B7\u03BA\u03B5 \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03BA\u03B1\u03B8\u03B9\u03C3\u03C4\u03AC \u03B1\u03B4\u03CD\u03BD\u03B1\u03C4\u03BF \u03C4\u03BF \u03C0\u03AC\u03B3\u03C9\u03BC\u03B1 \u03C4\u03C9\u03BD \u03C7\u03C1\u03B7\u03BC\u03AC\u03C4\u03C9\u03BD \u03C3\u03B1\u03C2. \u03A4\u03B1 CBDC \u03B4\u03B9\u03B5\u03C5\u03BA\u03BF\u03BB\u03CD\u03BD\u03BF\u03C5\u03BD \u03C4\u03BF \u03C0\u03AC\u03B3\u03C9\u03BC\u03B1.",
