	"point_9_summary_1": "\u03A4\u03BF Bitcoin \u03AD\u03C7\u03B5\u03B9 \u03C0\u03C1\u03BF\u03B2\u03BB\u03AD\u03C8\u03B9\u03BC\u03B7 \u03BD\u03BF\u03BC\u03B9\u03C3\u03BC\u03B1\u03C4\u03B9\u03BA\u03AE \u03C0\u03BF\u03BB\u03B9\u03C4\u03B9\u03BA\u03AE \u03B3\u03C1\u03B1\u03BC\u03BC\u03AD\u03BD\u03B7 \u03C3\u03C4\u03BF\u03BD \u03BA\u03CE\u03B4\u03B9\u03BA\u03B1. \u03A4\u03B1 CBDC \u03AD\u03C7\u03BF\u03C5\u03BD \u03BC\u03B5\u03C4\u03B1\u03B2\u03BB\u03B7\u03C4\u03AE \u03C0\u03BF\u03BB\u03B9\u03C4\u03B9\u03BA\u03AE.", "point_9_summary_2": "\u0391\u03C5\u03C4\u03CC \u03BF\u03B4\u03B7\u03B3\u03B5\u03AF \u03C3\u03B5 \u03C0\u03BB\u03B7\u03B8\u03C9\u03C1\u03B9\u03C3\u03BC\u03CC.",
	"point_10_summary_1": "\u03A4\u03BF Bitcoin \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C4\u03BF \u03B1\u03C3\u03C6\u03B1\u03BB\u03AD\u03C3\u03C4\u03B5\u03C1\u03BF \u03B4\u03AF\u03BA\u03C4\u03C5\u03BF \u03C5\u03C0\u03BF\u03BB\u03BF\u03B3\u03B9\u03C3\u03C4\u03CE\u03BD \u03C0\u03BF\u03C5 \u03C5\u03C0\u03AE\u03C1\u03BE\u03B5 \u03C0\u03BF\u03C4\u03AD. \u03A4\u03B1 CBDC \u03B5\u03BE\u03B1\u03C1\u03C4\u03CE\u03BD\u03C4\u03B1\u03B9 \u03B1\u03C0\u03CC \u03BA\u03C5\u03B2\u03B5\u03C1\u03BD\u03AE\u03C3\u03B5\u03B9\u03C2 \u03BA\u03B1\u03B9 \u03C4\u03C1\u03AC\u03C0\u03B5\u03B6\u03B5\u03C2."
