	"real_estate_header": "\u0397 \u0394\u0399\u0391\u03A6\u039F\u03A1\u0391", "real_estate_header_2": "\u039C\u0395\u03A4\u0391\u039E\u03A5", "real_estate_header_3": "BITCOIN", "real_estate_header_4": "\u039A\u0391\u0399 \u0391\u039A\u0399\u039D\u0397\u03A4\u03A9\u039D",
	"real_estate_intro_1": "\u03A4\u03B1 \u03B1\u03BA\u03AF\u03BD\u03B7\u03C4\u03B1 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B4\u03B7\u03BC\u03BF\u03C6\u03B9\u03BB\u03AE\u03C2 \u03B5\u03C0\u03AD\u03BD\u03B4\u03C5\u03C3\u03B7 \u03B5\u03B4\u03CE \u03BA\u03B1\u03B9 \u03B4\u03B5\u03BA\u03B1\u03B5\u03C4\u03AF\u03B5\u03C2.", "real_estate_intro_2": "\u03A4\u03BF Bitcoin \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C8\u03B7\u03C6\u03B9\u03B1\u03BA\u03CC \u03C7\u03C1\u03AE\u03BC\u03B1 \u03C0\u03BF\u03C5 \u03C0\u03BF\u03BB\u03BB\u03BF\u03AF \u03B8\u03B5\u03C9\u03C1\u03BF\u03CD\u03BD \u03B1\u03C0\u03BF\u03B8\u03AE\u03BA\u03B7 \u03B1\u03BE\u03AF\u03B1\u03C2.", "real_estate_intro_3": "\u0391\u03C2 \u03B4\u03BF\u03CD\u03BC\u03B5 \u03C4\u03B9\u03C2 \u03B4\u03B9\u03B1\u03C6\u03BF\u03C1\u03AD\u03C2: Bitcoin vs \u03B1\u03BA\u03AF\u03BD\u03B7\u03C4\u03B1.",
