	"visa_point_1": "\u039A\u03BB\u03B5\u03B9\u03C3\u03C4\u03CC \u03B4\u03AF\u03BA\u03C4\u03C5\u03BF", "visa_point_2": "3% \u03C0\u03C1\u03BF\u03BC\u03AE\u03B8\u03B5\u03B9\u03B5\u03C2 \u03B5\u03BC\u03C0\u03CC\u03C1\u03C9\u03BD", "visa_point_3": "\u0391\u03B4\u03B9\u03B1\u03C6\u03B1\u03BD\u03AD\u03C2 \u03C3\u03CD\u03C3\u03C4\u03B7\u03BC\u03B1", "visa_point_4": "\u039C\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03C0\u03B1\u03B3\u03CE\u03C3\u03B5\u03B9 \u03BB\u03BF\u03B3\u03B1\u03C1\u03B9\u03B1\u03C3\u03BC\u03BF\u03CD\u03C2", "visa_point_5": "\u0394\u03B7\u03BC\u03B9\u03BF\u03C5\u03C1\u03B3\u03B5\u03AF \u03C7\u03C1\u03AD\u03BF\u03C2 \u03BC\u03B5 \u03C5\u03C8\u03B7\u03BB\u03AC \u03B5\u03C0\u03B9\u03C4\u03CC\u03BA\u03B9\u03B1", "visa_point_6": "\u0391\u03C0\u03B1\u03B9\u03C4\u03B5\u03AF \u03BC\u03B5\u03C3\u03AC\u03B6\u03BF\u03BD\u03C4\u03B5\u03C2", "visa_point_7": "\u03A0\u03B5\u03C1\u03B9\u03BF\u03C1\u03B9\u03C3\u03BC\u03AD\u03BD\u03BF\u03B9 \u03C7\u03C1\u03CC\u03BD\u03BF\u03B9 \u03BA\u03B1\u03B9 \u03B3\u03B5\u03C9\u03B3\u03C1\u03B1\u03C6\u03AF\u03B1",
	"bitcoin_point_1": "\u0391\u03BD\u03BF\u03B9\u03C7\u03C4\u03CC \u03B4\u03AF\u03BA\u03C4\u03C5\u03BF", "bitcoin_point_2": "\u039A\u03B1\u03BC\u03AF\u03B1 \u03C0\u03C1\u03BF\u03BC\u03AE\u03B8\u03B5\u03B9\u03B1 \u03B5\u03BC\u03C0\u03CC\u03C1\u03C9\u03BD", "bitcoin_point_3": "\u0394\u03B9\u03B1\u03C6\u03B1\u03BD\u03AD\u03C2 \u03C3\u03CD\u03C3\u03C4\u03B7\u03BC\u03B1", "bitcoin_point_4": "\u0394\u03B5\u03BD \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03C0\u03B1\u03B3\u03CE\u03C3\u03B5\u03B9", "bitcoin_point_5": "\u039A\u03B1\u03BC\u03AF\u03B1 \u03B4\u03B7\u03BC\u03B9\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03C7\u03C1\u03AD\u03BF\u03C5\u03C2", "bitcoin_point_6": "\u0394\u03C5\u03BD\u03B1\u03C4\u03CC\u03C4\u03B7\u03C4\u03B1 \u03B1\u03C5\u03C4\u03BF-\u03C6\u03CD\u03BB\u03B1\u03BE\u03B7\u03C2", "bitcoin_point_7": "\u03A0\u03B1\u03B3\u03BA\u03CC\u03C3\u03BC\u03B9\u03B1 \u03C0\u03C1\u03CC\u03C3\u03B2\u03B1\u03C3\u03B7 24/7",
	"point_1_summary_1": "\u03A4\u03BF Bitcoin \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B1\u03BD\u03BF\u03B9\u03C7\u03C4\u03CC \u03B4\u03AF\u03BA\u03C4\u03C5\u03BF \u03C3\u03C4\u03BF \u03BF\u03C0\u03BF\u03AF\u03BF \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03C3\u03C5\u03BC\u03BC\u03B5\u03C4\u03AC\u03C3\u03C7\u03B5\u03B9 \u03BF\u03C0\u03BF\u03B9\u03BF\u03C3\u03B4\u03AE\u03C0\u03BF\u03C4\u03B5.", "point_1_summary_2": "\u0391\u03C5\u03C4\u03CC \u03BA\u03AC\u03BD\u03B5\u03B9 \u03C4\u03BF Bitcoin \u03C0\u03B9\u03BF \u03C3\u03C5\u03BC\u03C0\u03B5\u03C1\u03B9\u03BB\u03B7\u03C0\u03C4\u03B9\u03BA\u03CC \u03BA\u03B1\u03B9 \u03C0\u03C1\u03BF\u03C3\u03B2\u03AC\u03C3\u03B9\u03BC\u03BF.",
	"point_2_summary_1": "\u039F\u03B9 \u03C3\u03C5\u03BD\u03B1\u03BB\u03BB\u03B1\u03B3\u03AD\u03C2 Bitcoin \u03B4\u03B5\u03BD \u03AD\u03C7\u03BF\u03C5\u03BD \u03C0\u03C1\u03BF\u03BC\u03AE\u03B8\u03B5\u03B9\u03B5\u03C2 \u03B5\u03BC\u03C0\u03CC\u03C1\u03C9\u03BD, \u03B5\u03BD\u03CE \u03BF\u03B9 \u03C0\u03B9\u03C3\u03C4\u03C9\u03C4\u03B9\u03BA\u03AD\u03C2 \u03BA\u03AC\u03C1\u03C4\u03B5\u03C2 \u03C7\u03C1\u03B5\u03CE\u03BD\u03BF\u03C5\u03BD \u03C0\u03B5\u03C1\u03AF\u03C0\u03BF\u03C5 3%.", "point_2_summary_2": "\u039C\u03AC\u03B8\u03B5\u03C4\u03B5 \u03C0\u03CE\u03C2 \u03B7 \u03B5\u03C0\u03B9\u03C7\u03B5\u03AF\u03C1\u03B7\u03C3\u03AE \u03C3\u03B1\u03C2 \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03B5\u03BE\u03BF\u03B9\u03BA\u03BF\u03BD\u03BF\u03BC\u03AE\u03C3\u03B5\u03B9", "point_2_summary_3": "\u03B4\u03B5\u03C7\u03CC\u03BC\u03B5\u03BD\u03B7 Bitcoin \u03B1\u03BD\u03C4\u03AF \u03B3\u03B9\u03B1 \u03C0\u03B9\u03C3\u03C4\u03C9\u03C4\u03B9\u03BA\u03AD\u03C2 \u03BA\u03AC\u03C1\u03C4\u03B5\u03C2.",
	"point_3_summary_1": "\u03A4\u03BF Bitcoin \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03B5\u03AF \u03C3\u03B5 \u03B4\u03B9\u03B1\u03C6\u03B1\u03BD\u03AD\u03C2 blockchain. \u03A4\u03B1 \u03B4\u03AF\u03BA\u03C4\u03C5\u03B1 \u03C0\u03B9\u03C3\u03C4\u03C9\u03C4\u03B9\u03BA\u03CE\u03BD \u03BA\u03B1\u03C1\u03C4\u03CE\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03BA\u03BB\u03B5\u03B9\u03C3\u03C4\u03AC.", "point_3_summary_2": "\u0397 \u03B4\u03B9\u03B1\u03C6\u03AC\u03BD\u03B5\u03B9\u03B1 \u03BA\u03AC\u03BD\u03B5\u03B9 \u03C4\u03BF Bitcoin \u03C0\u03B9\u03BF \u03B1\u03BE\u03B9\u03CC\u03C0\u03B9\u03C3\u03C4\u03BF.",
	"point_4_summary_1": "\u039F\u03B9 \u03B5\u03C4\u03B1\u03B9\u03C1\u03B5\u03AF\u03B5\u03C2 \u03C0\u03B9\u03C3\u03C4\u03C9\u03C4\u03B9\u03BA\u03CE\u03BD \u03BA\u03B1\u03C1\u03C4\u03CE\u03BD \u03BC\u03C0\u03BF\u03C1\u03BF\u03CD\u03BD \u03BD\u03B1 \u03C0\u03B1\u03B3\u03CE\u03C3\u03BF\u03C5\u03BD \u03BB\u03BF\u03B3\u03B1\u03C1\u03B9\u03B1\u03C3\u03BC\u03BF\u03CD\u03C2 \u03B1\u03BD\u03AC \u03C0\u03AC\u03C3\u03B1 \u03C3\u03C4\u03B9\u03B3\u03BC\u03AE. \u03A4\u03BF Bitcoin \u03B4\u03B5\u03BD \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03C0\u03B1\u03B3\u03CE\u03C3\u03B5\u03B9.", "point_4_summary_2": "\u039C\u03B5 \u03C4\u03BF Bitcoin \u03B4\u03B9\u03B1\u03C4\u03B7\u03C1\u03B5\u03AF\u03C4\u03B5 \u03C4\u03BF\u03BD \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF \u03C4\u03C9\u03BD \u03C7\u03C1\u03B7\u03BC\u03AC\u03C4\u03C9\u03BD \u03C3\u03B1\u03C2.",
	"point_5_summary_1": "\u039F\u03B9 \u03C0\u03B9\u03C3\u03C4\u03C9\u03C4\u03B9\u03BA\u03AD\u03C2 \u03BA\u03AC\u03C1\u03C4\u03B5\u03C2 \u03B4\u03B7\u03BC\u03B9\u03BF\u03C5\u03C1\u03B3\u03BF\u03CD\u03BD \u03C7\u03C1\u03AD\u03BF\u03C2 \u03BC\u03B5 \u03B5\u03C0\u03B9\u03C4\u03CC\u03BA\u03B9\u03B1 \u03C0\u03BF\u03C5 \u03BC\u03C0\u03BF\u03C1\u03BF\u03CD\u03BD \u03BD\u03B1 \u03C5\u03C0\u03B5\u03C1\u03B2\u03BF\u03CD\u03BD \u03C4\u03BF 25%.", "point_5_summary_2": "\u039F\u03B9 \u03C3\u03C5\u03BD\u03B1\u03BB\u03BB\u03B1\u03B3\u03AD\u03C2 Bitcoin \u03B5\u03AF\u03BD\u03B1\u03B9 \u03BF\u03C1\u03B9\u03C3\u03C4\u03B9\u03BA\u03AD\u03C2 \u03C7\u03C9\u03C1\u03AF\u03C2 \u03C7\u03C1\u03AD\u03BF\u03C2.",
	"point_6_summary_1": "\u03A4\u03BF Bitcoin \u03B5\u03C0\u03B9\u03C4\u03C1\u03AD\u03C0\u03B5\u03B9 \u03B1\u03C5\u03C4\u03BF-\u03C6\u03CD\u03BB\u03B1\u03BE\u03B7, \u03B4\u03B7\u03BB\u03B1\u03B4\u03AE \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF\u03C4\u03B5 \u03BD\u03B1 \u03BA\u03C1\u03B1\u03C4\u03AC\u03C4\u03B5 \u03BA\u03B1\u03B9 \u03BD\u03B1 \u03B5\u03BB\u03AD\u03B3\u03C7\u03B5\u03C4\u03B5 \u03C4\u03B1 \u03C7\u03C1\u03AE\u03BC\u03B1\u03C4\u03AC \u03C3\u03B1\u03C2.", "point_6_summary_2": "\u039C\u03AC\u03B8\u03B5\u03C4\u03B5 \u03C0\u03B5\u03C1\u03B9\u03C3\u03C3\u03CC\u03C4\u03B5\u03C1\u03B1 \u03B3\u03B9\u03B1 \u03C4\u03B1 \u03C0\u03BF\u03C1\u03C4\u03BF\u03C6\u03CC\u03BB\u03B9\u03B1 Bitcoin", "point_6_summary_3": "\u03B3\u03B9\u03B1 \u03BD\u03B1 \u03BA\u03B1\u03C4\u03B1\u03BB\u03AC\u03B2\u03B5\u03C4\u03B5 \u03C0\u03CE\u03C2 \u03BD\u03B1 \u03C0\u03AC\u03C1\u03B5\u03C4\u03B5 \u03C4\u03BF\u03BD \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF.",
	"point_7_summary_1": "\u03A4\u03BF Bitcoin \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03B5\u03AF 24/7 \u03C0\u03B1\u03B3\u03BA\u03BF\u03C3\u03BC\u03AF\u03C9\u03C2.", "point_7_summary_2": "\u03A4\u03B1 \u03B4\u03AF\u03BA\u03C4\u03C5\u03B1 \u03C0\u03B9\u03C3\u03C4\u03C9\u03C4\u03B9\u03BA\u03CE\u03BD \u03BA\u03B1\u03C1\u03C4\u03CE\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C0\u03B5\u03C1\u03B9\u03BF\u03C1\u03B9\u03C3\u03BC\u03AD\u03BD\u03B1 \u03C3\u03B5 \u03CE\u03C1\u03B5\u03C2 \u03BA\u03B1\u03B9 \u03B3\u03B5\u03C9\u03B3\u03C1\u03B1\u03C6\u03AF\u03B1."
